ValidationResult SchemaValidator::validate(const ConfigValue& value, const std::string& fieldPath) {
    ValidationResult result;
    
    // Apply custom validators
    for (const auto& [path, validator] : customValidators) {
        if (fieldPath == path || fieldPath.find(path + ".") == 0) {
            if (!validator(value)) {
                result.addError(errorMessage, 
                               ValidationError::ErrorSeverity::Error,
                               ValidationError::ErrorCategory::CustomError,
                               fieldPath);
            }
        }
    }
    
    return result;
}

