ValidationResult DynamicValidator::validateWithContext(const ConfigValue& value, const std::string& fieldPath,
                                                      const std::unordered_map<std::string, ConfigValue>& context) {
    ValidationResult result;
    
    // Apply context-aware validation
    // This is a simplified implementation - could be expanded with more sophisticated context handling
    if (context.find("environment") != context.end()) {
        auto envValue = context.at("environment");
        if (TypeValidator::isString(envValue)) {
            std::string env = std::get<std::string>(envValue);
            if (env == "production" && TypeValidator::isString(value)) {
                const std::string& str = std::get<std::string>(value);
                if (str.empty()) {
                    result.addError("Configuration cannot be empty in production environment",
                                   ValidationError::ErrorSeverity::Critical,
                                   ValidationError::ErrorCategory::ConstraintError,
                                   fieldPath);
                }
            }
        }
    }
    
    return result;
}

