ValidationResult DynamicValidator::validate(const ConfigValue& value, const std::string& fieldPath) {
    ValidationResult result;
    
    // Apply runtime validators
    for (const auto& [path, validator, severity] : runtimeValidators) {
        if (fieldPath == path || fieldPath.find(path + ".") == 0) {
            auto validatorResult = validator(value);
            for (const auto& error : validatorResult.getErrors()) {
                result.addError(error);
            }
        }
    }
    
    return result;
}

