ValidationResult NeuralNetworkValidator::validateTrainingParams(const ConfigValue& value, const std::string& fieldPath) {
    ValidationResult result;
    
    // Simplified training parameters validation
    if (TypeValidator::isNested(value)) {
        auto& params = std::get<std::map<std::string, nlohmann::json>>(value);
        
        // Validate learning rate
        if (params.find("learning_rate") != params.end()) {
            auto lrValue = params["learning_rate"];
            if (lrValue.is_number()) {
                double lr = lrValue.get<double>();
                if (lr < 0.0001 || lr > 1.0) {
                    result.addError("Learning rate must be between 0.0001 and 1.0",
                                   ValidationError::ErrorSeverity::Error,
                                   ValidationError::ErrorCategory::ConstraintError,
                                   fieldPath + ".learning_rate");
                }
            }
        }
        
        // Validate batch size
        if (params.find("batch_size") != params.end()) {
            auto batchValue = params["batch_size"];
            if (batchValue.is_number_integer() && batchValue.get<int>() <= 0) {
                result.addError("Batch size must be positive",
                               ValidationError::ErrorSeverity::Error,
                               ValidationError::ErrorCategory::ConstraintError,
                               fieldPath + ".batch_size");
            }
        }
    }
    
    return result;
}

ValidationResult NeuralNetworkValidator::validateInferenceParams(const ConfigValue& value, const std::string& fieldPath) {
    ValidationResult result;
    
    // Simplified inference parameters validation
    if (TypeValidator::isNested(value)) {
        auto& params = std::get<std::map<std::string, nlohmann::json>>(value);
        
        // Validate confidence threshold
        if (params.find("confidence_threshold") != params.end()) {
            auto threshValue = params["confidence_threshold"];
            if (threshValue.is_number()) {
                double thresh = threshValue.get<double>();
                if (thresh < 0.0 || thresh > 1.0) {
                    result.addError("Confidence threshold must be between 0.0 and 1.0",
                                   ValidationError::ErrorSeverity::Error,
                                   ValidationError::ErrorCategory::ConstraintError,
                                   fieldPath + ".confidence_threshold");
                }
            }
        }
    }
    
    return result;
}

// Implementation of ValidationManager
ValidationResult ValidationManager::validateWithMutex(const ConfigValue& value, const std::string& fieldPath,
                                                      bool continueOnError) {
    std::lock_guard<std::mutex> lock(mutex);
    
    ValidationResult result;
    metrics.totalFieldsValidated++;
    
    // Apply field-specific validators
    auto fieldIt = fieldValidators.find(fieldPath);
    if (fieldIt != fieldValidators.end()) {
        for (const auto& validator : fieldIt->second) {
            if (!validator->isActive()) continue;
            
            auto validatorResult = validator->validate(value, fieldPath);
            for (const auto& error : validatorResult.getErrors()) {
                result.addError(error);
                metrics.totalErrors++;
                metrics.errorsByField[fieldPath]++;
                if (error.getSeverity() == ValidationError::ErrorSeverity::Warning) {
                    metrics.totalWarnings++;
                } else if (error.getSeverity() == ValidationError::ErrorSeverity::Critical) {
                    metrics.totalCriticalErrors++;
                }
            }
            
            if (continueOnError) {
                // Continue processing even with errors
                continue;
            }
            
            if (validatorResult.shouldStopProcessing()) {
                break;
            }
        }
    }
    
    return result;
}

ValidationResult ValidationManager::registerValidator(const std::string& fieldPath,
                                                     std::unique_ptr<Validator> validator,
                                                     bool override) {
    ValidationResult result;
    std::lock_guard<std::mutex> lock(mutex);
    
    if (!enabled) {
        return result;
    }
    
    if (!override) {
        auto fieldIt = fieldValidators.find(fieldPath);
        if (fieldIt != fieldValidators.end()) {
            for (const auto& existingValidator : fieldIt->second) {
                if (existingValidator->getName() == validator->getName()) {
                    result.addError("Validator already registered for field " + fieldPath,
                                   ValidationError::ErrorSeverity::Warning,
                                   ValidationError::ErrorCategory::CustomError,
                                   fieldPath);
                    return result;
                }
            }
        }
    }
    
    fieldValidators[fieldPath].push_back(std::move(validator));
    return result;
}

ValidationResult ValidationManager::unregisterValidator(const std::string& fieldPath, const std::string& validatorName) {
    ValidationResult result;
    std::lock_guard<std::mutex> lock(mutex);
    
    auto fieldIt = fieldValidators.find(fieldPath);
    if (fieldIt != fieldValidators.end()) {
        auto& validators = fieldIt->second;
        validators.erase(
            std::remove_if(validators.begin(), validators.end(),
                          [&validatorName](const std::unique_ptr<Validator>& validator) {
                              return validator->getName() == validatorName;
                          }),
            validators.end()
        );
        
        if (validators.empty()) {
            fieldValidators.erase(fieldIt);
        }
    }
    
    return result;
}

std::vector<std::string> ValidationManager::getRegisteredFields() const {
    std::lock_guard<std::mutex> lock(mutex);
    std::vector<std::string> fields;
    for (const auto& entry : fieldValidators) {
        fields.push_back(entry.first);
    }
    return fields;
}

std::vector<std::string> ValidationManager::getValidatorsForField(const std::string& fieldPath) const {
    std::lock_guard<std::mutex> lock(mutex);
    std::vector<std::string> validatorNames;
    
    auto fieldIt = fieldValidators.find(fieldPath);
    if (fieldIt != fieldValidators.end()) {
        for (const auto& validator : fieldIt->second) {
            validatorNames.push_back(validator->getName());
        }
    }
    
    return validatorNames;
}

ValidationResult ValidationManager::validateField(const ConfigValue& value, const std::string& fieldPath,
                                                 bool continueOnError) {
    if (!enabled) {
        ValidationResult result;
        return result;
    }
    
    if (!threadSafe) {
        return validateWithMutex(value, fieldPath, continueOnError);
    } else {
        return validateWithMutex(value, fieldPath, continueOnError);
    }
}

ValidationResult ValidationManager::validateAll(const std::unordered_map<std::string, ConfigValue>& config,
                                               bool continueOnError) {
    ValidationResult result;
    result.setPartialValidation(!continueOnError);
    result.setFailFast(continueOnError);
    
    for (const auto& entry : config) {
        auto fieldResult = validateField(entry.second, entry.first, continueOnError);
        for (const auto& error : fieldResult.getErrors()) {
            result.addError(error);
        }
        
        if (!continueOnError && !fieldResult.isValid()) {
            break;
        }
    }
    
    metrics.endTime = std::chrono::steady_clock::now();
    return result;
}

ValidationResult ValidationManager::validateConfiguration(const Config& config,
                                                         bool continueOnError,
                                                         const std::unordered_map<std::string, ConfigValue>& context) {
    ValidationResult result;
    
    // Get all config entries
    std::vector<ConfigEntry> entries;
    
    // This would require accessing the Config's internal data
    // For now, we'll skip the actual extraction
    // In a real implementation, we would extract entries from the Config object
    
    result.setPartialValidation(!continueOnError);
    result.setFailFast(continueOnError);
    
    for (const auto& entry : entries) {
        auto fieldResult = validateField(entry.value, entry.key, continueOnError);
        for (const auto& error : fieldResult.getErrors()) {
            result.addError(error);
        }
        
        if (!continueOnError && !fieldResult.isValid()) {
            break;
        }
    }
    
    metrics.endTime = std::chrono::steady_clock::now();
    return result;
}

ValidationResult ValidationManager::validateWithSchema(const std::unordered_map<std::string, ConfigValue>& config,
                                                     const nlohmann::json& schema) {
    ValidationResult result;
    
    for (const auto& entry : config) {
        // Get the schema for this field
        if (schema.contains(entry.first)) {
            auto fieldSchema = schema[entry.first];
            
            if (fieldSchema.is_object()) {
                ValidationResult fieldResult = SchemaValidator("schema_validator").validateJSONSchema(
                    entry.second, entry.first, fieldSchema
                );
                for (const auto& error : fieldResult.getErrors()) {
                    result.addError(error);
                }
            }
        }
    }
    
    metrics.endTime = std::chrono::steady_clock::now();
    return result;
}

ValidationResult ValidationManager::addDynamicValidator(const std::string& fieldPath,
                                                        std::function<ValidationResult(const ConfigValue&)> validator) {
    ValidationResult result;
    std::lock_guard<std::mutex> lock(mutex);
    dynamicValidators[fieldPath].emplace_back(
        "dynamic_validator", validator, ValidationError::ErrorSeverity::Error
    );
    return result;
}

ValidationResult ValidationManager::removeDynamicValidator(const std::string& fieldPath, const std::string& validatorName) {
    ValidationResult result;
    std::lock_guard<std::mutex> lock(mutex);
    
    auto fieldIt = dynamicValidators.find(fieldPath);
    if (fieldIt != dynamicValidators.end()) {
        auto& validators = fieldIt->second;
        validators.erase(
            std::remove_if(validators.begin(), validators.end(),
                          [&validatorName](const std::tuple<std::string, std::function<ValidationResult(const ConfigValue&)>, ValidationError::ErrorSeverity>& t) {
                              return std::get<0>(t) == validatorName;
                          }),
            validators.end()
        );
        
        if (validators.empty()) {
            dynamicValidators.erase(fieldIt);
        }
    }
    
    return result;
}

